CREATE DATABASE IF NOT EXISTS election_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE election_db;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,role ENUM('superadmin','admin') NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,lrn CHAR(12) NOT NULL UNIQUE,username VARCHAR(50) NULL UNIQUE,password_hash VARCHAR(255) NULL,full_name VARCHAR(120) NOT NULL,grade VARCHAR(20) NOT NULL,section VARCHAR(50) NOT NULL,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',eligible TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE elections(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,description TEXT,guidelines TEXT,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,status ENUM('draft','open','closed') NOT NULL DEFAULT 'draft',results_published TINYINT(1) NOT NULL DEFAULT 0,created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE positions(id INT AUTO_INCREMENT PRIMARY KEY,election_id INT NOT NULL,name VARCHAR(100) NOT NULL,max_select TINYINT NOT NULL DEFAULT 1,sort INT NOT NULL DEFAULT 0,FOREIGN KEY(election_id) REFERENCES elections(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE candidates(id INT AUTO_INCREMENT PRIMARY KEY,election_id INT NOT NULL,position_id INT NOT NULL,student_id INT NOT NULL,photo VARCHAR(100),party VARCHAR(100),bio TEXT,credentials TEXT,platform TEXT,status ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',UNIQUE(election_id,student_id),FOREIGN KEY(election_id) REFERENCES elections(id) ON DELETE CASCADE,FOREIGN KEY(position_id) REFERENCES positions(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE announcements(id INT AUTO_INCREMENT PRIMARY KEY,election_id INT NULL,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(election_id) REFERENCES elections(id) ON DELETE CASCADE) ENGINE=InnoDB;
-- Who voted (identity only; no link to any ballot)
CREATE TABLE participation(election_id INT NOT NULL,student_id INT NOT NULL,voted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(election_id,student_id),FOREIGN KEY(election_id) REFERENCES elections(id),FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
-- Ballots hold no student id, no timestamp, random ids: secrecy preserved
CREATE TABLE ballots(id CHAR(32) PRIMARY KEY,election_id INT NOT NULL,FOREIGN KEY(election_id) REFERENCES elections(id)) ENGINE=InnoDB;
CREATE TABLE votes(id INT AUTO_INCREMENT PRIMARY KEY,ballot_id CHAR(32) NOT NULL,election_id INT NOT NULL,position_id INT NOT NULL,candidate_id INT NOT NULL,UNIQUE(ballot_id,candidate_id),FOREIGN KEY(ballot_id) REFERENCES ballots(id),FOREIGN KEY(position_id) REFERENCES positions(id),FOREIGN KEY(candidate_id) REFERENCES candidates(id)) ENGINE=InnoDB;
CREATE TABLE logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(60) NOT NULL,detail VARCHAR(255),ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(action,ip,created_at)) ENGINE=InnoDB;
